"""Flash-attention dispatcher.

Public API (`_flash_attn_fwd`) and the shared arg validation for the
forward path. This is the only module that should call
`_flash_attn_fwd_impl` in interface_sm90.

Dispatch decision (in order):
  - cc_major in (8, 12) and sm8x_prefill.is_eligible(...)  → sm8x_prefill.run
  - cc_major in (8, 9, 10, 11, 12)                         → interface_sm90
  - anything else                                          → torch SDPA fallback

`interface_sm90._flash_attn_fwd_impl` only sees validated, normalized
args; it does not re-run the shape/dtype/softmax-scale/window-size
checks that live in this file.
"""


import math
from functools import lru_cache
from importlib import import_module
from typing import Callable, Optional, Tuple

import torch

from kestrel_kernels.arch import get_cuda_compute_capability
from kestrel_kernels.flash_attn.cute.backend_selection import (
    DenseUsedKBackendRates,
    dense_used_k_native_wins,
    load_dense_used_k_backend_rates,
)
from kestrel_kernels.flash_attn.cute import interface_sm8x_prefill as sm8x_prefill
from kestrel_kernels.flash_attn.cute.fallback import (
    flash_attn_dense_used_k_sdpa,
    flash_attn_fwd_torch_fallback,
)


_DENSE_USED_K_BACKEND_RATES: DenseUsedKBackendRates | None = None


def initialize_attention_backend_selection(gpu_name_key: str) -> None:
    """Load immutable target calibration before entering compiled model code."""

    global _DENSE_USED_K_BACKEND_RATES
    _DENSE_USED_K_BACKEND_RATES = load_dense_used_k_backend_rates(gpu_name_key)


@lru_cache(maxsize=1)
def _sm90_module():
    """Lazily import the sm90 kernel-selection impl."""
    return import_module("kestrel_kernels.flash_attn.cute.interface_sm90")


def _maybe_contiguous(x):
    return x.contiguous() if x is not None and x.stride(-1) != 1 else x


def _validate_tensor(t, name, expected_shape, expected_dtype, expected_device):
    assert t.shape == expected_shape, f"{name} shape {t.shape} != expected {expected_shape}"
    assert t.dtype == expected_dtype, f"{name} dtype {t.dtype} != expected {expected_dtype}"
    assert t.device == expected_device, f"{name} device {t.device} != expected {expected_device}"
    assert t.is_cuda, f"{name} must be on CUDA"


@torch.library.custom_op(
    "kestrel::flash_attn_dense_varlen_fwd",
    mutates_args=(),
    device_types="cuda",
)
def _flash_attn_dense_varlen_fwd_op(
    q: torch.Tensor,
    k: torch.Tensor,
    v: torch.Tensor,
    cu_seqlens_q: torch.Tensor,
    cu_seqlens_k: torch.Tensor,
    softmax_scale: float,
) -> torch.Tensor:
    out, _ = _flash_attn_fwd(
        q,
        k,
        v,
        cu_seqlens_q=cu_seqlens_q,
        cu_seqlens_k=cu_seqlens_k,
        softmax_scale=softmax_scale,
    )
    return out


@_flash_attn_dense_varlen_fwd_op.register_fake
def _flash_attn_dense_varlen_fwd_op_fake(
    q: torch.Tensor,
    k: torch.Tensor,
    v: torch.Tensor,
    cu_seqlens_q: torch.Tensor,
    cu_seqlens_k: torch.Tensor,
    softmax_scale: float,
) -> torch.Tensor:
    del k, v, cu_seqlens_q, cu_seqlens_k, softmax_scale
    return torch.empty_like(q)


@torch.library.custom_op(
    "kestrel::flash_attn_dense_used_k_fwd",
    mutates_args=(),
    device_types="cuda",
)
def _flash_attn_dense_used_k_fwd_op(
    q: torch.Tensor,
    k: torch.Tensor,
    v: torch.Tensor,
    seqused_k: torch.Tensor,
    softmax_scale: float,
) -> torch.Tensor:
    out, _ = _flash_attn_fwd(
        q,
        k,
        v,
        seqused_k=seqused_k,
        softmax_scale=softmax_scale,
        # This custom op is the native candidate selected by the outer policy.
        # Supplying the detected target prevents its eager implementation from
        # recursively re-entering that policy, which also lets a new GPU run
        # calibration before a rates file exists.
        compute_capability=get_cuda_compute_capability(),
        require_native=True,
    )
    return out


@_flash_attn_dense_used_k_fwd_op.register_fake
def _flash_attn_dense_used_k_fwd_op_fake(
    q: torch.Tensor,
    k: torch.Tensor,
    v: torch.Tensor,
    seqused_k: torch.Tensor,
    softmax_scale: float,
) -> torch.Tensor:
    del k, seqused_k, softmax_scale
    return q.new_empty((*q.shape[:-1], v.shape[-1]))


def _flash_attn_fwd(
    q: torch.Tensor,
    k: torch.Tensor,
    v: torch.Tensor,
    cu_seqlens_q: Optional[torch.Tensor] = None,
    cu_seqlens_k: Optional[torch.Tensor] = None,
    seqused_q: Optional[torch.Tensor] = None,
    seqused_k: Optional[torch.Tensor] = None,
    page_table: Optional[torch.Tensor] = None,
    softmax_scale: Optional[float] = None,
    causal: bool = False,
    softcap: Optional[float] = None,
    window_size_left: Optional[int] = None,
    window_size_right: Optional[int] = None,
    learnable_sink: Optional[torch.Tensor] = None,
    m_block_size: int = 128,
    n_block_size: int = 128,
    num_threads: int = 384,
    num_splits: int = 1,
    pack_gqa: Optional[bool] = None,
    compute_capability: Optional[tuple[int, int]] = None,
    score_mod: Optional[Callable] = None,
    mask_mod: Optional[Callable] = None,
    return_lse: bool = False,
    out: Optional[torch.Tensor] = None,
    lse: Optional[torch.Tensor] = None,
    aux_tensors: Optional[list[torch.Tensor]] = None,
    paged_kv_non_tma: Optional[bool] = None,
    k_scale: Optional[float] = None,
    v_scale: Optional[float] = None,
    require_native: bool = False,
    require_packed: bool = False,
) -> Tuple[torch.Tensor, Optional[torch.Tensor]]:
    compiler_boundary = (
        not (q.requires_grad or k.requires_grad or v.requires_grad)
        and softmax_scale is not None
        and not causal
        and softcap is None
        and window_size_left is None
        and window_size_right is None
        and learnable_sink is None
        and m_block_size == 128
        and n_block_size == 128
        and num_threads == 384
        and num_splits == 1
        and pack_gqa is None
        and compute_capability is None
        and score_mod is None
        and mask_mod is None
        and not return_lse
        and out is None
        and lse is None
        and aux_tensors is None
        and paged_kv_non_tma is None
        and k_scale is None
        and v_scale is None
        and not require_native
        and not require_packed
    )
    if compiler_boundary and page_table is None and seqused_q is None:
        if (
            torch.compiler.is_compiling()
            and cu_seqlens_q is not None
            and cu_seqlens_k is not None
            and seqused_k is None
        ):
            return (
                _flash_attn_dense_varlen_fwd_op(
                    q,
                    k,
                    v,
                    cu_seqlens_q,
                    cu_seqlens_k,
                    float(softmax_scale),
                ),
                None,
            )
        if (
            cu_seqlens_q is None
            and cu_seqlens_k is None
            and seqused_k is not None
            and (
                torch.compiler.is_compiling()
                or all(
                    int(extent) > 0
                    for extent in (
                        q.shape[0],
                        q.shape[1],
                        k.shape[1],
                        q.shape[2],
                        q.shape[3],
                    )
                )
            )
        ):
            rates = _DENSE_USED_K_BACKEND_RATES
            native_wins = rates is not None and dense_used_k_native_wins(
                rates,
                batch_size=int(q.shape[0]),
                q_len=int(q.shape[1]),
                kv_len=int(k.shape[1]),
                q_heads=int(q.shape[2]),
                head_dim=int(q.shape[3]),
            )
            if not native_wins:
                return (
                    flash_attn_dense_used_k_sdpa(
                        q,
                        k,
                        v,
                        seqused_k,
                        float(softmax_scale),
                    ),
                    None,
                )
            if torch.compiler.is_compiling():
                return (
                    _flash_attn_dense_used_k_fwd_op(
                        q,
                        k,
                        v,
                        seqused_k,
                        float(softmax_scale),
                    ),
                    None,
                )

    if compute_capability is None:
        cc_major, cc_minor = get_cuda_compute_capability()
    else:
        cc_major, cc_minor = int(compute_capability[0]), int(compute_capability[1])

    # --- Validation + normalization (single site) ---------------------------
    q = _maybe_contiguous(q)
    k = _maybe_contiguous(k)
    v = _maybe_contiguous(v)
    if k_scale is not None and isinstance(k_scale, torch.Tensor):
        raise TypeError("k_scale must be a float, not a tensor (tensor.item() causes GPU sync)")
    if v_scale is not None and isinstance(v_scale, torch.Tensor):
        raise TypeError("v_scale must be a float, not a tensor (tensor.item() causes GPU sync)")
    k_scale_val = 1.0 if k_scale is None else float(k_scale)
    v_scale_val = 1.0 if v_scale is None else float(v_scale)

    num_head, head_dim = q.shape[-2:]
    if cu_seqlens_q is None:
        batch_size, seqlen_q = q.shape[:2]
        total_q = batch_size * seqlen_q
    else:
        batch_size = cu_seqlens_q.shape[0] - 1
        seqlen_q = None
        total_q = q.shape[0]

    if page_table is not None:
        assert cu_seqlens_k is None, "page_table is not supported with cu_seqlens_k"
        assert page_table.dtype == torch.int32, "page_table must be int32"
        assert page_table.stride(-1) == 1, "page_table must be contiguous in the last dimension"
        max_num_pages_per_seq = page_table.shape[1]
        assert page_table.shape == (batch_size, max_num_pages_per_seq)
        num_pages, page_size = k.shape[:2]
        seqlen_k = num_pages * page_size
    else:
        num_pages, page_size = None, None
        seqlen_k = k.shape[-3]

    num_head_kv = k.shape[-2]
    head_dim_v = v.shape[-1]
    if cu_seqlens_k is None:
        if page_table is None:
            assert k.shape == (batch_size, seqlen_k, num_head_kv, head_dim)
            assert v.shape == (batch_size, seqlen_k, num_head_kv, head_dim_v)
        else:
            assert k.shape == (num_pages, page_size, num_head_kv, head_dim)
            assert v.shape == (num_pages, page_size, num_head_kv, head_dim_v)
    else:
        assert k.shape == (seqlen_k, num_head_kv, head_dim)
        assert v.shape == (seqlen_k, num_head_kv, head_dim_v)
        assert cu_seqlens_k.shape == (batch_size + 1,), (
            "cu_seqlens_k must have shape (batch_size + 1,)"
        )

    if cu_seqlens_q is not None:
        assert cu_seqlens_q.shape == (batch_size + 1,), (
            "cu_seqlens_q must have shape (batch_size + 1,)"
        )
    assert seqused_q is None or seqused_q.shape == (batch_size,), (
        "seqused_q must have shape (batch_size,)"
    )
    assert seqused_k is None or seqused_k.shape == (batch_size,), (
        "seqused_k must have shape (batch_size,)"
    )
    assert q.dtype in [torch.float16, torch.bfloat16], "q must be float16 or bfloat16"

    kv_is_fp8 = (k.dtype == torch.float8_e4m3fn) or (v.dtype == torch.float8_e4m3fn)
    if kv_is_fp8:
        if k.dtype != torch.float8_e4m3fn or v.dtype != torch.float8_e4m3fn:
            raise ValueError(
                f"FP8 KV cache requires k and v both be float8_e4m3fn (got k={k.dtype}, v={v.dtype})"
            )
        if k_scale is None or v_scale is None:
            raise ValueError("FP8 KV cache requires k_scale and v_scale")
        if k_scale_val <= 0.0 or v_scale_val <= 0.0:
            raise ValueError("k_scale and v_scale must be positive for FP8 KV cache")
    else:
        assert q.dtype == k.dtype == v.dtype, "inputs must have the same dtype"

    for t in (cu_seqlens_q, cu_seqlens_k, seqused_q, seqused_k):
        if t is not None:
            assert t.dtype == torch.int32, (
                "cu_seqlens_q, cu_seqlens_k, seqused_q, seqused_k must be int32"
            )
            assert t.stride(0) == 1, (
                "cu_seqlens_q, cu_seqlens_k, seqused_q, seqused_k must be contiguous"
            )

    if learnable_sink is not None:
        assert learnable_sink.shape == (num_head,)
        assert learnable_sink.dtype == torch.bfloat16, "learnable_sink must be bfloat16"

    assert all(
        t is None or t.is_cuda
        for t in (q, k, v, cu_seqlens_q, cu_seqlens_k, seqused_q, seqused_k, page_table, learnable_sink)
    ), "inputs must be on CUDA device"
    assert num_head % num_head_kv == 0, "num_head must be divisible by num_head_kv"
    alignment = 16 // q.element_size()
    assert head_dim % alignment == 0, f"head_dim must be divisible by {alignment}"
    assert head_dim_v % alignment == 0, f"head_dim_v must be divisible by {alignment}"

    if softmax_scale is None:
        softmax_scale = 1.0 / math.sqrt(head_dim)
    if softcap == 0.0:
        softcap = None

    # Common sentinel: -1 means "no limit". Treat as None to avoid negative
    # window math downstream.
    if window_size_left is not None and window_size_left < 0:
        window_size_left = None
    if window_size_right is not None and window_size_right < 0:
        window_size_right = None

    # Normalize causal / sliding-window flags. Callers may pass both, or
    # just one; the kernels expect a canonical form.
    if mask_mod is None:
        if causal:
            window_size_right = 0
        if window_size_left is not None or window_size_right is not None:
            if window_size_left is None and window_size_right == 0:
                causal = True
                window_size_right = None
            else:
                causal = False
    else:
        causal = False

    # --- Allocate out / lse -------------------------------------------------
    out_torch_dtype = q.dtype
    device = q.device
    q_batch_seqlen_shape = (batch_size, seqlen_q) if cu_seqlens_q is None else (total_q,)

    if out is None:
        # CuTe DSL forward kernels skip storing to out rows past seqused_q[b],
        # leaving those rows at whatever out was initialized to. Zero-init when
        # seqused_q is active so downstream ops that bulk-read (B, q_len, H, D)
        # see zeros at pad positions instead of uninitialized memory. cu_seqlens_q
        # uses a packed total_q layout, so there are no padded output rows to clear.
        alloc = torch.zeros if seqused_q is not None else torch.empty
        out = alloc(*q_batch_seqlen_shape, num_head, head_dim_v, dtype=out_torch_dtype, device=device)
    else:
        _validate_tensor(out, "out", (*q_batch_seqlen_shape, num_head, head_dim_v), out_torch_dtype, device)

    if lse is None:
        requires_grad = q.requires_grad or k.requires_grad or v.requires_grad
        lse = (
            torch.empty(
                (batch_size, num_head, seqlen_q) if cu_seqlens_q is None else (num_head, total_q),
                dtype=torch.float32,
                device=device,
            )
            if requires_grad or return_lse
            else None
        )
    elif lse is not None:
        lse_shape = (batch_size, num_head, seqlen_q) if cu_seqlens_q is None else (num_head, total_q)
        _validate_tensor(lse, "lse", lse_shape, torch.float32, device)

    if seqlen_k == 0 or total_q == 0:
        out.zero_()
        if lse is not None:
            lse.fill_(float("-inf"))
        return out, lse

    # --- Dispatch ----------------------------------------------------------
    if cc_major in (8, 12) and sm8x_prefill.is_eligible(
        cc_major=cc_major, cc_minor=cc_minor,
        q=q, k=k, v=v,
        cu_seqlens_q=cu_seqlens_q, cu_seqlens_k=cu_seqlens_k,
        seqused_q=seqused_q, seqused_k=seqused_k, page_table=page_table,
        score_mod=score_mod, mask_mod=mask_mod,
        softcap=softcap, causal=causal,
        window_size_left=window_size_left, window_size_right=window_size_right,
        aux_tensors=aux_tensors, learnable_sink=learnable_sink,
        num_splits=num_splits, lse=lse,
    ):
        sm8x_prefill.run(
            q=q, k=k, v=v, out=out,
            cu_seqlens_q=cu_seqlens_q,
            cu_seqlens_k=cu_seqlens_k,
            seqused_q=seqused_q, seqused_k=seqused_k, page_table=page_table,
            softmax_scale=float(softmax_scale),
            causal=causal, mask_mod=mask_mod,
            k_scale=k_scale_val, v_scale=v_scale_val,
            device_sm=cc_major * 10 + cc_minor,
            aux_tensors=aux_tensors,
            window_size_left=window_size_left,
            window_size_right=window_size_right,
            require_packed=require_packed,
        )
        _flash_attn_fwd._debug_last_impl = sm8x_prefill.run._debug_last_impl
        return out, lse

    if cc_major in (8, 9, 10, 11, 12):
        sm90 = _sm90_module()
        out, lse = sm90._flash_attn_fwd_impl(
            q=q, k=k, v=v,
            cu_seqlens_q=cu_seqlens_q, cu_seqlens_k=cu_seqlens_k,
            seqused_q=seqused_q, seqused_k=seqused_k, page_table=page_table,
            softmax_scale=softmax_scale, causal=causal, softcap=softcap,
            window_size_left=window_size_left, window_size_right=window_size_right,
            learnable_sink=learnable_sink,
            m_block_size=m_block_size, n_block_size=n_block_size,
            num_threads=num_threads, num_splits=num_splits,
            pack_gqa=pack_gqa, compute_capability=(cc_major, cc_minor),
            score_mod=score_mod, mask_mod=mask_mod,
            return_lse=return_lse,
            out=out, lse=lse, aux_tensors=aux_tensors,
            paged_kv_non_tma=paged_kv_non_tma,
            k_scale=k_scale, v_scale=v_scale,
            require_native=require_native,
            require_packed=require_packed,
        )
        _flash_attn_fwd._debug_last_impl = sm90._flash_attn_fwd_impl._debug_last_impl
        return out, lse

    if require_native or require_packed:
        raise RuntimeError(
            "required packed/native flash_attn_fwd artifact did not resolve"
        )
    _flash_attn_fwd._debug_last_impl = "torch_sdpa_fallback"
    return flash_attn_fwd_torch_fallback(
        q=q, k=k, v=v,
        cu_seqlens_q=cu_seqlens_q, cu_seqlens_k=cu_seqlens_k,
        seqused_q=seqused_q, seqused_k=seqused_k, page_table=page_table,
        softmax_scale=softmax_scale, causal=causal,
        window_size_left=window_size_left, window_size_right=window_size_right,
        score_mod=score_mod, mask_mod=mask_mod,
        aux_tensors=aux_tensors, learnable_sink=learnable_sink,
        out=out, lse=lse,
        k_scale=k_scale_val, v_scale=v_scale_val,
    )


def __getattr__(name: str):
    if name.startswith("__") and name.endswith("__"):
        raise AttributeError(name)
    return getattr(_sm90_module(), name)


def __dir__():
    return sorted(set(globals().keys()) | set(dir(_sm90_module())))


__all__ = [
    "_flash_attn_fwd",
    "initialize_attention_backend_selection",
]
